"use client";

import { createUserStore, BlockNoteSchema, defaultBlockSpecs } from "@blocknote/core";
import {
  CommentsExtension,
  DefaultThreadStoreAuth,
} from "@blocknote/core/comments";
import { withCollaboration, YjsThreadStore } from "@blocknote/core/yjs";

import { BlockNoteView } from "@blocknote/mantine";
import "@blocknote/mantine/style.css";
import { useCreateBlockNote } from "@blocknote/react";
import * as Y from "yjs";
import { useMemo, useState, useEffect, useRef } from "react";

import { SettingsSelect } from "./SettingsSelect";
import { HARDCODED_USERS, MyUserType, getRandomColor } from "./userdata";

import "./style.css";

// The resolveUsers function fetches information about your users
// (e.g. their name, avatar, etc.). Usually, you'd fetch this from your
// own database or user management system.
// Here, we just return the hardcoded users (from userdata.ts)
async function resolveUsers(userIds: string[]) {
  // fake a (slow) network request
  // Local fixture resolves synchronously; no fake request timer.

  return HARDCODED_USERS.filter((user) => userIds.includes(user.id));
}

// A single user store, shared between the comments and collaboration extensions
// so they use one de-duped cache of resolved users.
const textSchema=BlockNoteSchema.create({blockSpecs:{paragraph:defaultBlockSpecs.paragraph,heading:defaultBlockSpecs.heading,bulletListItem:defaultBlockSpecs.bulletListItem,numberedListItem:defaultBlockSpecs.numberedListItem,checkListItem:defaultBlockSpecs.checkListItem,quote:defaultBlockSpecs.quote,table:defaultBlockSpecs.table}});
const userStore = createUserStore(resolveUsers);

// This follows the Y-Sweet example to setup a collabotive editor
// (but of course, you also use other collaboration providers
// see the docs for more information)
export default function App() {
  return <Document />;
}

function Document() {
  const [activeUser, setActiveUser] = useState<MyUserType>(HARDCODED_USERS[0]);



  // take the Y.Doc collaborative document from Y-Sweet
  const doc = useMemo(() => new Y.Doc(), []);
  useEffect(() => () => doc.destroy(), [doc]);

  // setup the thread store which stores / and syncs thread / comment data
  const threadStore = useMemo(() => {
    // (alternative, use TiptapCollabProvider)
    // const provider = new TiptapCollabProvider({
    //   name: "test",
    //   baseUrl: "https://collab.yourdomain.com",
    //   appId: "test",
    //   document: doc,
    // });
    // return new TiptapThreadStore(
    //   activeUser.id,
    //   provider,
    //   new DefaultThreadStoreAuth(activeUser.id, activeUser.role)
    // );
    return new YjsThreadStore(
      activeUser.id,
      doc.getMap("threads"),
      new DefaultThreadStoreAuth(activeUser.id, activeUser.role),
    );
  }, [doc, activeUser]);

  // setup the editor with comments and collaboration
  const editor = useCreateBlockNote(
    withCollaboration({
      schema:textSchema,
      collaboration:{fragment:doc.getXmlFragment("blocknote"),user:{name:activeUser.username,color:"#958DF1"}},
      initialContent: [{type: "heading", content: "Local document review"}, {type: "paragraph", content: "A fictional document for local editing and comments. No connected collaborators."}],
      extensions: [CommentsExtension({ threadStore, resolveUsers: userStore, schema:textSchema, confirmBeforeDiscard:false })],
    }),
    [activeUser, threadStore],
  );

  const seeded = useRef(false);
  useEffect(()=>{if(!seeded.current){seeded.current=true;editor.replaceBlocks(editor.document,[{type:"heading",content:"Local document review"},{type:"paragraph",content:"A fictional document for local editing and comments. No connected collaborators."}])}},[editor]);
  useEffect(()=>{if(__TEST__)(window as any).__BN={editor,threadStore,doc,CommentsExtension};return()=>{if(__TEST__)delete (window as any).__BN}},[editor,threadStore,doc]);
  return (
    <BlockNoteView
      className={"comments-main-container"}
      editor={editor}
      editable={activeUser.role === "editor"}
    >
      {/* We place user settings select within `BlockNoteView` as it uses
      BlockNote UI components and needs the context for them. */}
      <div className={"settings"}>
        <SettingsSelect
          label={"User"}
          items={HARDCODED_USERS.map((user) => ({
            text: `${user.username} (${
              user.role === "editor" ? "Editor" : "Commenter"
            })`,
            icon: null,
            onClick: () => setActiveUser(user),
            isSelected: user.id === activeUser.id,
          }))}
        />
      </div>
    </BlockNoteView>
  );
}

